};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.img_REG_INST_CD_onclick = function(e) {
    scwin.setFnGetParam("3"); // 등록기관

    $c.cm.ins_popupOpen(txb_REG_INST_CD, txb_REG_INST_NM, "ULDINS90100", "기관코드", "470", "420");
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.getParam = function() {
    scwin.arrPar[0] = scwin.param1;
    scwin.arrPar[1] = scwin.param2;

    return scwin.arrPar;
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    //scwin.arrPar, length;
};

scwin.setFnGetParam = function(vparam1) {
    scwin.param1 = vparam1;
    scwin.param2 = "";
    //fn_GetPar = fn_GetParam;
};
